package io.aetheris.orchestrator.trading;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="aetheris_stage9_paper_equity") public class PaperEquitySnapshotEntity {@Id private UUID id;private double cashBalance;private double equity;private double unrealizedPnl;private double grossExposure;private int openPositions;@Column(nullable=false) private Instant observedAt;protected PaperEquitySnapshotEntity(){}public PaperEquitySnapshotEntity(UUID id,double cash,double equity,double unrealized,double gross,int open){this.id=id;this.cashBalance=cash;this.equity=equity;this.unrealizedPnl=unrealized;this.grossExposure=gross;this.openPositions=open;this.observedAt=Instant.now();}public UUID getId(){return id;}public double getCashBalance(){return cashBalance;}public double getEquity(){return equity;}public double getUnrealizedPnl(){return unrealizedPnl;}public double getGrossExposure(){return grossExposure;}public int getOpenPositions(){return openPositions;}public Instant getObservedAt(){return observedAt;}}
